1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import { encryptSecret } from "./crypto-box";
7	import { checkRateLimit } from "./rate-limit";
8	import { SANDBOX } from "./sandbox";
9	import { withServerSsh, exec, QUICK_TIMEOUT_MS } from "./ssh-exec";
10	import { detectSource, syntheticScan, parseSizeLabel, type ScanResult } from "../worker/migrate-detect";
11	import { cleanHostname, pointHostnameToIp } from "./cloudflare-point";
12	import { readStoredCloudflare } from "./cloudflare-oauth";
13	
14	export type { ScanResult } from "../worker/migrate-detect";
15	
16	/**
17	 * VPS migration — pull a customer's files + databases from another provider's
18	 * VPS onto their new Nxeon server. The customer supplies SSH credentials for the
19	 * SOURCE box; we only ever verify ownership of the TARGET (Nxeon) server.
20	 *
21	 * All source secrets (the SSH password and each database password) are encrypted
22	 * at rest with the shared AES-256-GCM box in lib/crypto-box.ts (`encryptSecret`),
23	 * the SAME helper used for mailbox/BYOK secrets. They are CLEARED by the worker
24	 * (worker/migrate.ts) the moment the migration finishes — success or failure —
25	 * so a completed Migration row never retains usable credentials. Nothing here
26	 * ever returns a decrypted secret (or the ciphertext) to the client.
27	 *
28	 * The heavy lifting runs in the `MIGRATE` worker job; this module only validates
29	 * input, encrypts secrets, records the Migration row and enqueues the job.
30	 */
31	
32	// ---- Input shapes (mirrors the Migration.items Json) ------------------------
33	
34	export type CreateMigrationInput = {
35	  serverId: string; // target Nxeon server (must be owned by the caller)
36	  sourceHost: string; // FQDN or IP of the source VPS
37	  sourcePort?: number; // SSH port, default 22
38	  sourceUser?: string; // SSH user, default "root" (we use root's LOCAL auth to dump DBs)
39	  sourcePassword: string; // SSH password for the source box
40	  paths?: string[]; // file paths to copy from the source (to the same paths on the target)
41	  /**
42	   * Read-only auto-detection snapshot (from scanSource). Carries NO secrets. We
43	   * derive the whole lift-and-shift plan (which DB engines to dump passwordlessly,
44	   * Docker volumes/compose dirs, prerequisites to install, ports to verify) from
45	   * it, and store both the plan and the snapshot under Migration.items — reusing
46	   * the existing Json column rather than adding a schema field (another agent
47	   * owns the schema this wave).
48	   */
49	  scan?: ScanResult;
50	  /**
51	   * Explicit opt-in to use an attached block-storage volume for Docker's stores
52	   * (`/var/lib/docker` + `/var/lib/containerd`). **Defaults to false.**
53	   *
54	   * Volumes are portable: the Volumes UI promises they can be attached to any of
55	   * the customer's running servers, and their data survives a server rebuild.
56	   * Mounting a system path on a volume silently ends that — the server can no
57	   * longer boot properly without it. So this is never inferred from free space;
58	   * the customer ticks a box in the wizard that says so in as many words. Stored
59	   * under Migration.items (an existing Json column) — no schema change.
60	   */
61	  useVolumeForDocker?: boolean;
62	};
63	
64	// The passwordless lift-and-shift plan, derived from the scan + selected paths and
65	// carried through Migration.items (secret-free). The worker re-validates every
66	// value against strict shell-inert allowlists before it is used in a command.
67	type MigrationPlan = {
68	  dbEngines: ("mysql" | "postgres")[];
69	  dockerVolumes: string[];
70	  composeDirs: string[];
71	  verifyPorts: number[];
72	  hasContainers: boolean;
73	  webServers: ("nginx" | "apache")[];
74	  runtimes: ("nodejs" | "python3")[];
75	};
76	
77	// ---- Client-safe row shapes (NEVER include secrets) -------------------------
78	
79	export type MigrationDatabaseView = {
80	  engine: string;
81	  name: string;
82	  user: string;
83	};
84	
85	export type MigrationRow = {
86	  id: string;
87	  serverId: string;
88	  serverName: string | null;
89	  sourceHost: string;
90	  sourcePort: number;
91	  sourceUser: string;
92	  paths: string[];
93	  databases: MigrationDatabaseView[];
94	  status: string;
95	  progress: number;
96	  step: string | null;
97	  log: string | null;
98	  lastError: string | null;
99	  createdAt: string;
100	  finishedAt: string | null;
101	};
102	
103	// ---- Validation -------------------------------------------------------------
104	
105	// Hostname/FQDN (RFC-1123-ish) or IPv4 literal. Deliberately permissive on IPv6
106	// (a bracketed/colon form is accepted) — the worker's SSH layer does the final
107	// resolution; this only rejects obvious junk before we store anything.
108	const HOST_RE =
109	  /^(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)*[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?|\d{1,3}(?:\.\d{1,3}){3}|\[?[0-9a-fA-F:]+\]?)$/;
110	const DEFAULT_PATHS = ["/var/www", "/home"];
111	const MAX_PATHS = 40;
112	
113	function cleanPaths(paths: string[] | undefined): string[] {
114	  const list = (paths && paths.length ? paths : DEFAULT_PATHS)
115	    .map((p) => p.trim())
116	    .filter((p) => p.length > 0 && p.startsWith("/") && !p.includes("\0"));
117	  // De-dupe while preserving order.
118	  return [...new Set(list)].slice(0, MAX_PATHS);
119	}
120	
121	// Docker volume names are shell-inert (docker's own charset) — the worker
122	// re-validates, but we only ever store well-formed names.
123	const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
124	function isCopyableAbsPath(p: string): boolean {
125	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
126	}
127	
128	/**
129	 * Derive the passwordless lift-and-shift plan from the read-only scan and the set
130	 * of paths the customer chose to copy. Databases are auto-included whenever an
131	 * engine was detected (no password needed — the worker dumps via root's local
132	 * socket/peer auth); Docker/web/runtime prerequisites are inferred so the worker
133	 * can install them on the target. Everything here is secret-free.
134	 */
135	function derivePlan(scan: ScanResult | undefined, selectedPaths: string[]): MigrationPlan {
136	  const empty: MigrationPlan = {
137	    dbEngines: [],
138	    dockerVolumes: [],
139	    composeDirs: [],
140	    verifyPorts: [],
141	    hasContainers: false,
142	    webServers: [],
143	    runtimes: [],
144	  };
145	  if (!scan || !scan.ok) return empty;
146	  const pathSet = new Set(selectedPaths);
147	
148	  // Auto-include every detected engine (dump passwordlessly via root local auth).
149	  const dbEngines = [...new Set((scan.engines ?? []).filter((e) => e.present).map((e) => e.engine))].filter(
150	    (e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres"
151	  );
152	
153	  const containers = scan.containers ?? [];
154	  // Named Docker volumes = container mounts that are NOT absolute host paths.
155	  const dockerVolumes = [
156	    ...new Set(
157	      containers.flatMap((c) => c.mounts ?? []).filter((m) => !isCopyableAbsPath(m) && VOLNAME_RE.test(m))
158	    ),
159	  ].slice(0, 60);
160	
161	  // Compose project dirs among the app dirs the customer is actually copying.
162	  const composeDirs = [
163	    ...new Set((scan.appDirs ?? []).filter((a) => a.signature === "compose" && pathSet.has(a.path)).map((a) => a.path)),
164	  ].slice(0, 40);
165	
166	  const verifyPorts = [
167	    ...new Set((scan.ports ?? []).map((p) => p.port).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22)),
168	  ].slice(0, 60);
169	
170	  const hasContainers = containers.length > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
171	
172	  // Web servers: match the owning process/service names, else default to nginx
173	  // when web roots exist (the overwhelmingly common case).
174	  const procBlob = [
175	    ...(scan.ports ?? []).map((p) => p.proc || ""),
176	    ...(scan.services ?? []).map((s) => s.name || ""),
177	  ]
178	    .join(" ")
179	    .toLowerCase();
180	  const webServers: ("nginx" | "apache")[] = [];
181	  if (/nginx/.test(procBlob)) webServers.push("nginx");
182	  if (/apache|httpd/.test(procBlob)) webServers.push("apache");
183	  if (webServers.length === 0 && (scan.webRoots ?? []).length > 0) webServers.push("nginx");
184	
185	  // Runtimes: from running-app runtimes and listening-port owners. Conservative.
186	  const runtimeBlob = [
187	    ...(scan.appDirs ?? []).map((a) => a.runtime || ""),
188	    ...(scan.ports ?? []).map((p) => p.proc || ""),
189	  ]
190	    .join(" ")
191	    .toLowerCase();
192	  const runtimes: ("nodejs" | "python3")[] = [];
193	  if (/node|next|pm2/.test(runtimeBlob)) runtimes.push("nodejs");
194	  if (/python|gunicorn|uvicorn|celery/.test(runtimeBlob)) runtimes.push("python3");
195	
196	  return { dbEngines, dockerVolumes, composeDirs, verifyPorts, hasContainers, webServers, runtimes };
197	}
