251	async function ownedTargetServer(serverId: string) {
252	  const user = await requireUser();
253	  const server = await db.server.findUnique({ where: { id: serverId } });
254	  if (!server) throw new Error("Not found");
255	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
256	  return { user, server };
257	}
