259	function toRow(
260	  m: {
261	    id: string;
262	    serverId: string;
263	    sourceHost: string;
264	    sourcePort: number;
265	    sourceUser: string;
266	    items: unknown;
267	    status: string;
268	    progress: number;
269	    step: string | null;
270	    log: string | null;
271	    lastError: string | null;
272	    createdAt: Date;
273	    finishedAt: Date | null;
274	  },
275	  server: { hostname: string; label: string | null } | null
276	): MigrationRow {
277	  const items = (m.items ?? {}) as {
278	    paths?: string[];
279	    databases?: { engine?: string; name?: string; user?: string }[];
280	    dbEngines?: string[];
281	  };
282	  // Databases are now auto-included per detected engine (no per-DB list). For the
283	  // client view, surface one row per engine; fall back to any legacy per-DB list.
284	  const dbView: MigrationDatabaseView[] =
285	    Array.isArray(items.databases) && items.databases.length
286	      ? items.databases.map((d) => ({
287	          engine: String(d.engine ?? ""),
288	          name: String(d.name ?? ""),
289	          user: String(d.user ?? ""),
290	        }))
291	      : Array.isArray(items.dbEngines)
292	        ? items.dbEngines.map((e) => ({ engine: String(e), name: "All databases", user: "root" }))
293	        : [];
294	  return {
295	    id: m.id,
296	    serverId: m.serverId,
297	    // Migration has no Prisma relation to Server (serverId is a plain FK), so the
298	    // caller resolves the server row and passes it in.
299	    serverName: server ? server.label || server.hostname : null,
300	    sourceHost: m.sourceHost,
301	    sourcePort: m.sourcePort,
302	    sourceUser: m.sourceUser,
303	    paths: Array.isArray(items.paths) ? items.paths : [],
304	    // Never expose any DB secret — dbView carries only non-sensitive fields.
305	    databases: dbView,
306	    status: m.status,
307	    progress: m.progress,
308	    step: m.step,
309	    log: m.log,
310	    lastError: m.lastError,
311	    createdAt: m.createdAt.toISOString(),
312	    finishedAt: m.finishedAt ? m.finishedAt.toISOString() : null,
313	  };
314	}
