318	/**
319	 * Start a migration onto one of the caller's Nxeon servers. Verifies TARGET
320	 * ownership, validates the source connection details, encrypts every source
321	 * secret, writes the Migration row (PENDING) and enqueues a MIGRATE job. Returns
322	 * the new migration id; never returns any secret.
323	 */
324	export async function createMigration(
325	  input: CreateMigrationInput
326	): Promise<{ error?: string; id?: string }> {
327	  const { user, server } = await ownedTargetServer(input.serverId);
328	
329	  // Rate-limit: a few migrations per user per 10 minutes is plenty and stops
330	  // credential-stuffing the wizard against arbitrary source hosts.
331	  const rl = checkRateLimit(`migrate:create:${user.id}`, { max: 5, windowMs: 10 * 60 * 1000 });
332	  if (!rl.ok) {
333	    return { error: `Too many migrations started — please wait ${rl.retryAfterSec}s and try again.` };
334	  }
335	
336	  const host = (input.sourceHost ?? "").trim();
337	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
338	    return { error: "Enter a valid source host — an IP address or domain name." };
339	  }
340	
341	  const port = input.sourcePort ?? 22;
342	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
343	    return { error: "SSH port must be between 1 and 65535." };
344	  }
345	
346	  const sourceUser = (input.sourceUser ?? "root").trim();
347	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
348	    return { error: "Enter the SSH username on the source server." };
349	  }
350	
351	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
352	    return { error: "Enter the SSH password for the source server." };
353	  }
354	
355	  const paths = cleanPaths(input.paths);
356	
357	  // Derive the passwordless lift-and-shift plan from the scan + selected paths.
358	  // Databases are auto-included when an engine is detected — no DB password is
359	  // ever collected; the worker dumps via root's local socket/peer auth.
360	  const plan = derivePlan(input.scan, paths);
361	
362	  // Persist the (secret-free) detection snapshot alongside the plan so the
363	  // migration is traceable back to what auto-detection found. Reusing items
364	  // avoids a schema change (Migration.items is a Json column).
365	  const scanSnapshot =
366	    input.scan && input.scan.ok
367	      ? {
368	          webRoots: input.scan.webRoots?.slice(0, 40) ?? [],
369	          homes: input.scan.homes?.slice(0, 40) ?? [],
370	          databases: input.scan.databases?.slice(0, 60) ?? [],
371	          engines: input.scan.engines ?? [],
372	          // Exact engine variant + version — lets the worker install the MATCHING
373	          // engine on the target for a clean same-engine restore.
374	          dbEngines: input.scan.dbEngines ?? [],
375	          // Running-app discovery — informational, secret-free, for traceability.
376	          appDirs: input.scan.appDirs?.slice(0, 40) ?? [],
377	          containers: input.scan.containers?.slice(0, 30) ?? [],
378	          ports: input.scan.ports?.slice(0, 60) ?? [],
379	          services: input.scan.services?.slice(0, 30) ?? [],
380	          // Storage-guardrail + compatibility inputs (secret-free, for traceability
381	          // and the worker pre-flight).
382	          dbSizeBytes: Math.max(0, input.scan.dbSizeBytes ?? 0),
383	          sourceOs: input.scan.sourceOs ?? null,
384	          sourceArch: input.scan.sourceArch ?? null,
385	          synthetic: !!input.scan.synthetic,
386	        }
387	      : undefined;
388	
389	  // Trusted server-side total of what will be migrated (bytes) — carried through
390	  // items so the worker's pre-flight guard can compare it to target free disk
391	  // without re-scanning. No schema change: Migration.items is a Json column.
392	  const totalBytes = selectedMigrationBytes(input.scan, paths);
393	
394	  const items = {
395	    paths,
396	    dbEngines: plan.dbEngines,
397	    dockerVolumes: plan.dockerVolumes,
398	    composeDirs: plan.composeDirs,
399	    verifyPorts: plan.verifyPorts,
400	    hasContainers: plan.hasContainers,
401	    webServers: plan.webServers,
402	    runtimes: plan.runtimes,
403	    totalBytes,
404	    // Explicit consent only — coerced to a real boolean so nothing else can ride
405	    // in on this field, and only ever true when the customer ticked the box.
406	    useVolumeForDocker: input.useVolumeForDocker === true,
407	    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
408	  };
409	
410	  const migration = await db.migration.create({
411	    data: {
412	      userId: user.id,
413	      serverId: server.id,
414	      sourceHost: host,
415	      sourcePort: port,
416	      sourceUser,
417	      sourcePasswordEnc: encryptSecret(input.sourcePassword),
418	      items,
419	      status: "PENDING",
420	      progress: 0,
421	      step: "Queued",
422	    },
423	  });
424	
425	  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
426	  // traceability); the handler loads everything else from payload.migrationId.
427	  await db.job.create({
428	    data: {
429	      type: "MIGRATE",
430	      serverId: server.id,
431	      payload: { migrationId: migration.id },
432	    },
433	  });
434	
435	  await db.auditLog.create({
436	    data: {
437	      userId: user.id,
438	      action: "migration.create",
439	      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
440	    },
441	  });
442	
443	  revalidatePath("/dashboard/migrate");
444	  return { id: migration.id };
445	}
