447	/**
448	 * READ-ONLY auto-detection of a source box for the beginner wizard. Verifies the
449	 * caller owns the TARGET server (authz + a stricter rate limit than create),
450	 * validates the source connection details, then SSHes into the source and
451	 * inventories web roots / home directories / databases — never writing anything
452	 * on the source and never persisting the supplied credentials.
453	 *
454	 * The plaintext SSH/DB passwords are used in-memory for this one call only and
455	 * are NOT stored anywhere; the client re-supplies them to createMigration once
456	 * the customer confirms what to move. Returns a secret-free ScanResult.
457	 *
458	 * In SANDBOX (staging) this returns realistic SYNTHETIC results and never opens
459	 * a real SSH connection, so staging stays fully self-contained.
460	 */
461	export async function scanSource(input: {
462	  serverId: string;
463	  sourceHost: string;
464	  sourcePort?: number;
465	  sourceUser?: string;
466	  sourcePassword: string;
467	  dbUser?: string;
468	  dbPassword?: string;
469	}): Promise<{ error?: string; scan?: ScanResult }> {
470	  const { user } = await ownedTargetServer(input.serverId);
471	
472	  // Scanning SSHes into an arbitrary customer-named host, so throttle it harder
473	  // than migration creation to stop the wizard being used to probe hosts.
474	  const rl = checkRateLimit(`migrate:scan:${user.id}`, { max: 8, windowMs: 10 * 60 * 1000 });
475	  if (!rl.ok) {
476	    return { error: `Too many scans — please wait ${rl.retryAfterSec}s and try again.` };
477	  }
478	
479	  const host = (input.sourceHost ?? "").trim();
480	  if (!host || host.length > 253 || !HOST_RE.test(host)) {
481	    return { error: "Enter a valid source host — an IP address or domain name." };
482	  }
483	  const port = input.sourcePort ?? 22;
484	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
485	    return { error: "SSH port must be between 1 and 65535." };
486	  }
487	  const sourceUser = (input.sourceUser ?? "root").trim();
488	  if (!sourceUser || sourceUser.length > 64 || /\s/.test(sourceUser)) {
489	    return { error: "Enter the SSH username on the source server." };
490	  }
491	  if (!input.sourcePassword || input.sourcePassword.length < 1) {
492	    return { error: "Enter the SSH password for the source server." };
493	  }
494	
495	  await db.auditLog.create({
496	    data: { userId: user.id, action: "migration.scan", detail: `${sourceUser}@${host}:${port}` },
497	  }).catch(() => {});
498	
499	  // SANDBOX: never touch the outside world — hand back synthetic detection.
500	  if (SANDBOX) {
501	    return { scan: syntheticScan({ dbPassword: input.dbPassword }) };
502	  }
503	
504	  // Hard overall timeout so a slow/hostile source can't hang the request.
505	  const HARD_TIMEOUT_MS = 90_000;
506	  try {
507	    const scan = await Promise.race<ScanResult>([
508	      detectSource({
509	        host,
510	        port,
511	        user: sourceUser,
512	        password: input.sourcePassword,
513	        dbUser: input.dbUser?.trim() || undefined,
514	        dbPassword: input.dbPassword || undefined,
515	      }),
516	      new Promise<ScanResult>((_, reject) =>
517	        setTimeout(() => reject(new Error("Scan timed out — the source server took too long to respond.")), HARD_TIMEOUT_MS)
518	      ),
519	    ]);
520	    return { scan };
521	  } catch (e: any) {
522	    const msg = `${e?.message ?? e}`;
523	    // Map the common connection failures to friendly, non-leaky copy.
524	    if (/authentication|denied|password/i.test(msg)) {
525	      return { error: "Couldn't sign in to the source server — check the SSH username and password." };
526	    }
527	    if (/ECONNREFUSED|ETIMEDOUT|EHOSTUNREACH|ENOTFOUND|timed out|getaddrinfo/i.test(msg)) {
528	      return { error: "Couldn't reach the source server — check the host and SSH port." };
529	    }
530	    return { error: "We couldn't scan that server. Double-check the details and try again." };
531	  }
532	}
