534	// ---- Target free-space + OS probe (storage & compatibility guardrails) ------
535	
536	export type TargetInfo = {
537	  /** null when the server is unreachable / df couldn't be parsed → soft warning. */
538	  disk: { totalBytes: number; usedBytes: number; availBytes: number } | null;
539	  os: { id: string; versionId: string; pretty: string } | null;
540	  arch: string | null;
541	  /**
542	   * Capacity of the LARGEST attached-but-unformatted block device (a volume the
543	   * customer added but hasn't used yet), or null if there isn't one.
544	   *
545	   * This is capacity that is available **only if the customer chooses to use it**
546	   * — the engine can format it and relocate the container stores onto it, but it
547	   * never does so on its own (see `useVolumeForDocker`). Volumes are portable
548	   * add-on storage, and mounting a system path on one makes it undetachable, so
549	   * the wizard presents this as an opt-in, not as free space.
550	   *
551	   * The LARGEST, not the sum: separate volumes are separate filesystems and the
552	   * engine uses exactly one. They are deliberately never combined into an LVM
553	   * pool — that would weld them together and destroy the portability of all of
554	   * them at once.
555	   */
556	  spareDiskBytes?: number | null;
557	  /**
558	   * How many unused volumes are attached. 2+ means the panel should say that only
559	   * the largest can be used, so the customer isn't left expecting them to add up.
560	   */
561	  spareDiskCount?: number | null;
562	};
563	
564	/**
565	 * Probe a destination Nxeon server (owner-only) for its root-filesystem free
566	 * space and OS/architecture, so the wizard can show the storage headroom and the
567	 * OS-compatibility guardrail. Read-only: `df -B1`, `uname -m`, and a grep of
568	 * `/etc/os-release`. In SANDBOX returns synthetic values (never opens SSH).
569	 *
570	 * Failure is graceful: if the server is unreachable or df can't be parsed we
571	 * return `disk: null` (the UI shows "couldn't read free space" and allows the
572	 * migration with a soft warning rather than a hard block). OS falls back to the
573	 * server's known OS template; arch defaults to x86_64 (all our VMs are x86_64).
574	 */
575	export async function targetDiskFree(
576	  serverId: string
577	): Promise<{ error?: string; info?: TargetInfo }> {
578	  const { server } = await ownedTargetServer(serverId);
579	
580	  // OS fallback from the known OS template (works even if the box is unreachable).
581	  const tmpl = await db.osTemplate
582	    .findUnique({ where: { id: server.osTemplateId }, select: { family: true, version: true, name: true } })
583	    .catch(() => null);
584	  const osFallback = tmpl
585	    ? {
586	        id: (tmpl.family || "linux").toLowerCase(),
587	        versionId: tmpl.version || "",
588	        pretty: `${tmpl.name}${tmpl.version ? ` ${tmpl.version}` : ""}`,
589	      }
590	    : null;
591	
592	  if (SANDBOX) {
593	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
594	    return {
595	      info: {
596	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
597	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
598	        arch: "x86_64",
599	      },
600	    };
601	  }
602	
603	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
604	  const full = await db.server.findUnique({
605	    where: { id: server.id },
606	    include: { dedicatedIp: true },
607	  });
608	
609	  try {
610	    const info = await withServerSsh(full as any, async (conn) => {
611	      // Root filesystem size/used/avail in bytes.
612	      const dfr = await exec(
613	        conn,
614	        "df -B1 --output=size,used,avail / 2>/dev/null | tail -n1",
615	        QUICK_TIMEOUT_MS
616	      );
617	      const nums = (dfr.stdout || "").trim().split("\n").pop()?.trim().split(/\s+/).map(Number) ?? [];
618	      let disk: TargetInfo["disk"] = null;
619	      if (nums.length >= 3 && nums.slice(0, 3).every((n) => Number.isFinite(n) && n > 0)) {
620	        disk = { totalBytes: nums[0], usedBytes: nums[1], availBytes: nums[2] };
621	      }
622	      const un = await exec(conn, "uname -m 2>/dev/null", QUICK_TIMEOUT_MS).catch(() => ({ stdout: "" }) as any);
623	      const arch = ((un.stdout as string) || "").trim().replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) || null;
624	      const osr = await exec(
625	        conn,
626	        "grep -E '^(ID|VERSION_ID|PRETTY_NAME)=' /etc/os-release 2>/dev/null || true",
627	        QUICK_TIMEOUT_MS
628	      ).catch(() => ({ stdout: "" }) as any);
629	      const os = parseOsRelease((osr.stdout as string) || "") ?? osFallback;
630	      // Attached-but-unformatted disks (unused volumes the customer added).
631	      // Read-only probe, and it mirrors the engine's qualification bar exactly so
632	      // the panel can never promise space the engine would refuse to touch: a
633	      // disk counts only when nothing in its tree has a filesystem or mount, it
634	      // has no children, nothing holds it, `blkid` finds no signature at all,
635	      // and it is at least the engine's 4 GiB floor.
636	      let spareDiskBytes: number | null = null;
637	      let spareDiskCount: number | null = null;
638	      try {
639	        const lb = await exec(
640	          conn,
641	          "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
642	            "[ -n \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ] && continue; " +
643	            "[ -n \"$(lsblk -no NAME /dev/$d 2>/dev/null | tail -n +2)\" ] && continue; " +
644	            "[ -n \"$(ls -A /sys/block/$d/holders 2>/dev/null)\" ] && continue; " +
645	            "blkid /dev/$d >/dev/null 2>&1 && continue; " +
646	            "sz=$(lsblk -bdn -o SIZE /dev/$d 2>/dev/null | tr -d ' '); " +
647	            "[ -z \"$sz\" ] && continue; " +
648	            "[ \"$sz\" -ge 4294967296 ] 2>/dev/null && echo \"$sz\"; done",
649	          QUICK_TIMEOUT_MS
650	        );
651	        const sizes = ((lb.stdout as string) || "")
652	          .split("\n")
653	          .map((s) => Number(s.trim()))
654	          .filter((n) => Number.isFinite(n) && n > 0);
655	        if (sizes.length) {
656	          // The LARGEST, never the sum — the engine uses exactly one volume and
657	          // does not combine them, so summing would promise space that no single
658	          // filesystem will ever have. The count lets the panel say so plainly.
659	          spareDiskCount = sizes.length;
660	          spareDiskBytes = Math.max(...sizes);
661	        }
662	      } catch {
