725	/** Pull a hostname out of a path like `/var/www/example.com` / `/home/example.com`. */
726	function hostnameFromPath(path: string): string | null {
727	  const leaf = String(path ?? "").split("/").filter(Boolean).pop() ?? "";
728	  const h = leaf.toLowerCase().replace(/^www\./, "");
729	  return cleanHostname(h);
730	}
731	
732	/**
733	 * Candidate domains to point at the migration's target server, cheapest source
734	 * first. Ownership-checked (the migration must be the caller's).
735	 *
736	 *   1. `Domain` rows — domains the customer registered with us.
737	 *   2. Websites already configured on the target server.
738	 *   3. Hostnames inferable from the STORED scan snapshot (`Migration.items.scan`)
739	 *      — web-root folders are conventionally named after the vhost. The snapshot
740	 *      does not record nginx/apache `server_name` values, so this is a best-effort
741	 *      read of what was already captured; we never re-scan the source.
742	 */
743	export async function getMigrationDnsInfo(migrationId: string): Promise<MigrationDnsInfo> {
744	  const user = await requireUser();
745	
746	  const m = await db.migration.findUnique({ where: { id: migrationId } });
747	  if (!m) return { error: "Migration not found." };
748	  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." };
749	
750	  const server = await db.server.findUnique({
751	    where: { id: m.serverId },
752	    select: { hostname: true, label: true, ipAddress: true, dedicatedIp: { select: { address: true } } },
753	  });
754	
755	  const seen = new Set<string>();
756	  const candidates: DnsCandidate[] = [];
757	  const push = (raw: string | null | undefined, source: DnsCandidate["source"]) => {
758	    const host = cleanHostname(raw ?? "");
759	    if (!host || seen.has(host)) return;
760	    seen.add(host);
761	    candidates.push({ host, source });
762	  };
763	
764	  const domains = await db.domain.findMany({
765	    where: { userId: m.userId },
766	    select: { name: true },
767	    orderBy: { name: "asc" },
768	    take: 50,
769	  });
770	  for (const d of domains) push(d.name, "registered");
771	
772	  const sites = await db.website.findMany({
773	    where: { serverId: m.serverId },
774	    select: { domain: true },
775	    take: 50,
776	  });
777	  for (const s of sites) push(s.domain, "website");
778	
779	  // Only what the scan already stored — no new source-scanning here.
780	  const items = (m.items ?? {}) as { scan?: { webRoots?: { path?: string }[] } };
781	  for (const w of items.scan?.webRoots ?? []) {
782	    if (w?.path) push(hostnameFromPath(w.path), "scan");
783	  }
784	
785	  return {
786	    targetIp: server?.dedicatedIp?.address ?? server?.ipAddress ?? null,
787	    targetName: server ? server.label || server.hostname : null,
788	    candidates: candidates.slice(0, 40),
789	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
790	  };
791	}
