793	/**
794	 * Point one hostname at the migration's TARGET server by upserting an A record in
795	 * the customer's Cloudflare zone — the last manual step of an otherwise one-click
796	 * migration.
797	 *
798	 * Guards: requireUser + migration ownership, rate-limited, and the hostname is
799	 * re-validated server-side (`cleanHostname` inside pointHostnameToIp) because
800	 * this one legitimately comes from customer input (the "enter a domain" box).
801	 * The record is DNS-only (proxied=false) so the name resolves to the server
802	 * itself and Let's Encrypt HTTP-01 validation can succeed there.
803	 */
804	export async function pointMigrationDns(
805	  migrationId: string,
806	  hostname: string
807	): Promise<{ ok: true; message: string } | { ok: false; error: string }> {
808	  const user = await requireUser();
809	
810	  const m = await db.migration.findUnique({ where: { id: migrationId } });
811	  if (!m) return { ok: false, error: "Migration not found." };
812	  if (m.userId !== user.id && user.role !== "ADMIN") return { ok: false, error: "Not your migration." };
813	
814	  const rl = checkRateLimit(`migrate:dns:${user.id}`, { max: 20, windowMs: 60_000 });
815	  if (!rl.ok) return { ok: false, error: `Too many requests — retry in ${rl.retryAfterSec}s.` };
816	
817	  const server = await db.server.findUnique({
818	    where: { id: m.serverId },
819	    select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
820	  });
821	  const ip = server?.dedicatedIp?.address ?? server?.ipAddress ?? null;
822	  if (!ip) {
823	    return { ok: false, error: "Your new server doesn't have a public IP yet — try again shortly." };
824	  }
825	
826	  const res = await pointHostnameToIp({
827	    user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
828	    hostname,
829	    ip,
830	  });
831	  if (!res.ok) return { ok: false, error: res.error };
832	
833	  await db.auditLog.create({
834	    data: {
835	      userId: user.id,
836	      action: "migration.dns",
837	      detail: `${res.hostname} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
838	    },
839	  });
840	
841	  return {
842	    ok: true,
843	    message: res.simulated
844	      ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). Nothing was sent to Cloudflare.`
845	      : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). It can take a few minutes for visitors to see the new server.`,
846	  };
847	}
