          for (const b of brokenCerts.slice(0, 8)) {
            if (await resolvesHere(conn, b.name, targetIp)) {
              await ensureAcmeWebroot(conn);
              await ensurePackages(conn, ["certbot"], (l) => report(91, "Checking for leftovers…", l));
              const r = await withHeartbeat(`requesting the missing certificate for ${b.name}`, (l) => report(91, "Checking for leftovers…", l), () =>
                issueHttp01(conn, b.name, [b.name], email)
              );
              if (r.ok) {
                issued++;
                continue;
              }
            }
            stillBroken.push(b);
          }
          if (issued) {
            push({
              step: `Re-issue ${issued} missing TLS certificate(s)`,
              status: "running",
              detail: "configuration referenced certificates that did not come across; they were obtained on this server so the referencing services can start",
            });
            await sh(conn, `nginx -t >/dev/null 2>&1 && systemctl reload nginx >/dev/null 2>&1; apachectl configtest >/dev/null 2>&1 && systemctl reload apache2 >/dev/null 2>&1; true`);
          }
          for (const b of stillBroken.slice(0, 6)) {
            push({
              step: `Missing TLS certificate for ${b.name}`,
              status: "failed",
              detail:
                `${b.file} references /etc/letsencrypt/live/${b.name}/ but no certificate for ${b.name} exists here, so whatever reads that file will fail to start. ` +
                `Once ${b.name} points at this server run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${b.name} -d ${b.name} — or remove the reference if that service is not being migrated.`,
            });
          }
        }
      }
    }

    // ---- 12. Verification: DB engines, containers, listening ports --------
    await report(92, "Verifying…", "Checking that databases, containers and services are up on the new server.");
    if (plan.dbEngines.includes("mysql")) {
      const up = await execRemote(conn, `systemctl is-active mariadb 2>/dev/null || systemctl is-active mysql 2>/dev/null || pgrep -x mysqld >/dev/null 2>&1 && echo active`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
      push({ step: "MySQL/MariaDB engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
    }
    if (plan.dbEngines.includes("postgres")) {
      const up = await execRemote(conn, `systemctl is-active postgresql 2>/dev/null || (pgrep -x postgres >/dev/null 2>&1 && echo active)`, SETUP_TIMEOUT_MS).then((x) => /active/.test(x.stdout)).catch(() => false);
      push({ step: "PostgreSQL engine", status: up ? "running" : "copied", detail: up ? "engine is active on the target" : "engine not confirmed active — start it manually" });
    }
    if (plan.hasContainers) {
      const n = await execRemote(conn, `docker ps -q 2>/dev/null | wc -l`, SETUP_TIMEOUT_MS).then((x) => parseInt(x.stdout.trim(), 10) || 0).catch(() => 0);
      push({ step: "Docker containers", status: n > 0 ? "running" : "copied", detail: n > 0 ? `${n} container(s) running on the target` : "no containers running yet — start your compose project(s)" });
      await report(94, "Verifying…", `  docker ps shows ${n} running container(s).`);
    }
    if (plan.verifyPorts.length) {
      const list = plan.verifyPorts.join(" ");
      const out = await execRemote(
        conn,
        `for p in ${list}; do (ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ":$p " && echo "$p up" || echo "$p down"; done`,
        SETUP_TIMEOUT_MS
      ).then((x) => x.stdout).catch(() => "");
      const upPorts = (out.match(/(\d+) up/g) ?? []).map((s) => s.replace(" up", ""));
      const downPorts = (out.match(/(\d+) down/g) ?? []).map((s) => s.replace(" down", ""));
      if (upPorts.length) push({ step: "Listening ports", status: "running", detail: `now listening on the target: ${upPorts.join(", ")}` });
      if (downPorts.length) push({ step: "Ports not yet listening", status: "copied", detail: `not up on the target yet: ${downPorts.join(", ")} — start the owning app/service` });
      await report(95, "Verifying…", `  ports up: ${upPorts.join(", ") || "none"}; not up: ${downPorts.join(", ") || "none"}.`);
    }

    // ---- 12b. DOES THE SITE ACTUALLY SERVE? -------------------------------
    // A listening port proves almost nothing: a real migration had the app up on
    // 127.0.0.1:3720, the port open, and every request answered by the stock
    // "Welcome to nginx" page — and a copied catch-all vhost happily answered 502
    // for everything. So we make a REAL request for each hostname, with
    // `curl --resolve` pinning it to this machine so the Host header and TLS SNI
    // are the customer's actual domain. Anything 1xx–4xx means the vhost matched
    // and something answered; 000 (nothing there) or 5xx does not.
    //
    // That was still not enough. On 2026-07-25 this check PASSED for a domain
    // that was answering 200 with the Apache2 Debian Default Page, and for a
    // domain that was being served a certificate belonging to a different site.
    // So a 1xx–4xx is now necessary but not sufficient, and there are three more
    // ways to fail:
    //   - the body is a distribution placeholder or effectively empty
    //     (defaultPageReason),
    //   - the certificate this server presents for the name does not cover it
    //     (servedCertNames — a browser shows a full-page security warning before
    //     the visitor ever reaches the site),
    //   - the name is simply not probed at all, because we never published it.
    //
    // And the LIST is now every hostname the SOURCE served, not the list we
    // generated a config for. See the note on `sourceDomains`.
    const siteProbes: { domain: string; http: string; https: string; serving: boolean; reason?: string }[] = [];
    const publishedNames = [...new Set(servedSites.flatMap((s) => s.names))];
    // Published names first (so the most important ones are inside the cap),
    // then everything else the old server answered on.
    const probeNames = [...new Set([...publishedNames, ...sourceDomains])].slice(0, 24);
    const unprobed = [...new Set([...publishedNames, ...sourceDomains])].slice(24);
    // Is anything at all listening on 443 here? Without that, https:// simply
    // refuses the connection and there is no certificate to mismatch.
    const tlsListening = await shOk(conn, `(ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ':443 '`);
    if (probeNames.length) {
      await report(
        96,
        "Verifying…",
        `Making a real request to each of your ${probeNames.length} domain(s) to confirm the site actually answers — and checking what it answers WITH.`
      );
      for (const d of probeNames) {
        const httpRes = await httpProbe(conn, `http://${d}/`, { domain: d, port: 80 });
        const hasCert = await certExists(conn, d);
        const httpsRes =
          hasCert || tlsSecured.includes(d)
            ? await httpProbe(conn, `https://${d}/`, { domain: d, port: 443 })
            : { code: "", body: "" };
        // With TLS present the HTTP block is a 301 to HTTPS, so HTTPS is the
        // authoritative answer; without it, HTTP is.
        const auth = httpsRes.code ? httpsRes : httpRes;
        let serving = isServing(auth.code);
        let reason = serving ? "" : auth.code === "000" ? "nothing answered at all" : `it answered ${auth.code}`;

        // (i) A 200 from a distribution placeholder is a dead site.
        if (serving) {
          const placeholder = defaultPageReason(auth.code, auth.body);
          if (placeholder) {
            serving = false;
            reason = placeholder;
          }
        }

        // (ii) The certificate a browser would actually be shown. Checked
        // whenever anything is listening on 443 — INCLUDING when we hold no
        // certificate for this name, because that is precisely the case where
        // another site's certificate gets served and the visitor is stopped by a
        // security warning (studionexis.com was served nexis.revsports.ca's).
        //
        // Skipped when a CONTAINER owns 443: there the proxy issues its own
        // certificates after DNS moves, so its placeholder self-signed cert
        // today says nothing about tomorrow, and the HTTPS summary entry already
        // explains that. The host is not the authority in that layout.
        if (serving && tlsListening && webKind !== "container") {
          const certNames = await servedCertNames(conn, d);
          if (certNames && !certCoversName(certNames, d)) {
            serving = false;
            reason =
              `this server answers https://${d}/ with a certificate issued for ${certNames.slice(0, 3).join(", ")}, which does not cover ${d} — ` +
              `every visitor gets a full-page browser security warning before they reach the site`;
          }
        }

        siteProbes.push({ domain: d, http: httpRes.code, https: httpsRes.code, serving, reason });
      }
      const good = siteProbes.filter((p) => p.serving);
      const bad = siteProbes.filter((p) => !p.serving);
      for (const p of good) {
        push({
          step: `Site ${p.domain}`,
          status: "running",
          detail: p.https
            ? `serving over HTTPS (HTTP ${p.http} → HTTPS ${p.https}) — point ${p.domain} at this server and it works`
            : `serving over HTTP (${p.http}) — no certificate yet, so visitors get a browser warning on https:// until one is issued`,
        });
      }
      for (const p of bad) {
        push({
          step: `Site ${p.domain} is NOT serving`,
          status: "failed",
          detail:
            p.http === "000" && !p.https
              ? `nothing answered for ${p.domain} on this server — the web server is not serving this name yet, so pointing DNS here would show an error`
              : `${p.reason || `${p.domain} answered ${p.https || p.http}`} — the old server answered on this name, so it is not migrated until this one does too. Check \`docker logs\` / \`systemctl status\` for the app behind it, then reload the web server`,
        });
        // Only if we do not already hold a better-targeted reason for this name
        // (the "could not publish" entry above knows exactly what was missing).
        if (!blockers.some((b) => b.domain === p.domain)) {
          blockers.push({
            domain: p.domain,
            why: p.reason || `it answered ${p.https || p.http} on the new server`,
            fix: `make ${p.domain} serve here (start the app behind it, add or fix its vhost, and issue a certificate that covers ${p.domain}), then re-run the check`,
          });
        }
      }
      await report(
        96,
        "Verifying…",
        `  serving: ${good.map((p) => p.domain).join(", ") || "none"}${bad.length ? `; NOT serving: ${bad.map((p) => p.domain).join(", ")}` : ""}.`
      );
      if (unprobed.length) {
        push({
          step: `${unprobed.length} more domain(s) were not checked`,
          status: "copied",
          detail: `${unprobed.slice(0, 8).join(", ")}${unprobed.length > 8 ? " …" : ""} — the old server also answered on these, but only the first ${probeNames.length} were probed. Check them by hand before moving DNS`,
        });
      }
    }
    // Independent of the per-domain probes above (which now also run in the
    // containerised layout, because the source's domains have to answer there
    // too): does the proxy container itself answer on port 80 at all?
    if (webKind === "container") {
      const code = await httpCode(conn, `http://127.0.0.1/`);
      push({
        step: "Site (containerised proxy)",
        status: isServing(code) ? "running" : "failed",
        detail: isServing(code)
          ? `your proxy container answers on port 80 (HTTP ${code}) — point your DNS here and it serves`
          : "nothing answered on port 80 — start your reverse-proxy container and check `docker logs`, or your domain will not resolve to anything",
      });
    }

    // ---- 13. Final honest summary ----------------------------------------
    // THE SCORE. Denominator = every hostname the SOURCE served (sourceDomains),
    // NOT the set we generated a config for. When the live inventory could not
    // run we have no honest denominator and fall back to the probed set, saying
    // so rather than quietly scoring ourselves against our own homework.
    const servingNow = siteProbes.filter((p) => p.serving).map((p) => p.domain);
    const servingSet = new Set(servingNow);
    const probedSet = new Set(probeNames);
    const scoredAgainst = sourceDomains.length ? sourceDomains : probeNames;
    // Everything the old server served that this one does not. A name we did not
    // get to probe counts here too — "we did not check" is not "it works" — but
    // it is worded separately so the customer is never told a site is broken when
    // what we actually mean is that we ran out of probe budget.
    const unservedDomains = scoredAgainst.filter((d) => !servingSet.has(d));
    const failedProbe = unservedDomains.filter((d) => probedSet.has(d));
    const uncheckedDomains = unservedDomains.filter((d) => !probedSet.has(d));

    // The distinct outcome. Anything on this list means the customer's move is
    // NOT finished, however many individual steps succeeded.
    const outcomeReasons: string[] = [];
    if (failedProbe.length) {
      outcomeReasons.push(
        `${failedProbe.length} of the ${scoredAgainst.length} domain(s) the old server answered on ${failedProbe.length === 1 ? "does" : "do"} not serve here: ${failedProbe.slice(0, 8).join(", ")}${failedProbe.length > 8 ? " …" : ""}`
      );
    }
    if (uncheckedDomains.length) {
      outcomeReasons.push(
        `${uncheckedDomains.length} domain(s) the old server answered on were not checked at all: ${uncheckedDomains.slice(0, 6).join(", ")}${uncheckedDomains.length > 6 ? " …" : ""}`
      );
    }
    if (unitBlockers.length) {
      outcomeReasons.push(
        `${unitBlockers.length} migrated service(s) are not running: ${unitBlockers.slice(0, 5).map((b) => b.domain).join(", ")}${unitBlockers.length > 5 ? " …" : ""}`
      );
    }
    if (!sourceDomains.length && probeNames.length) {
      outcomeReasons.push(
        "the old server's live configuration could not be read, so this score is measured against the sites we published rather than against everything the old server served — check the rest by hand"
      );
    }
    const outcome: MigrationOutcome = outcomeReasons.length ? "COMPLETED_WITH_ISSUES" : "COMPLETED";

    // The structured flag the UI keys off. worker/migrate.ts writes
    // Migration.status = "DONE" unconditionally and persists ONLY
    // summary.results into Migration.items.results — so the outcome is put at
    // the TOP of results as a first-class line with a `failed` status, which is
    // what actually reaches the customer's screen. `results.unshift` rather than
    // push(): this line SUMMARISES the other entries, so duplicating it into
    // needsAttention would just repeat every reason twice.
    results.unshift({
      step: outcome === "COMPLETED" ? "Migration outcome: COMPLETED" : "Migration outcome: COMPLETED_WITH_ISSUES",
      status: outcome === "COMPLETED" ? "running" : "failed",
      detail:
        outcome !== "COMPLETED"
          ? `this migration finished but is NOT done: ${outcomeReasons.join("; ")}. The individual entries below name each one with the command that fixes it.`
          : scoredAgainst.length
            ? `all ${scoredAgainst.length} domain(s) the old server answered on are serving on this server, and every migrated service is running`
            : "everything selected was migrated and verified; the old server did not serve any websites, so there was nothing to publish",
    });

    await report(
      97,
      "Finalising…",
      `Migrated & running (verified): ${verifiedRunning.length}. Copied — may need a manual step: ${needsAttention.length}.` +
        (scoredAgainst.length
          ? ` Sites actually serving: ${scoredAgainst.filter((d) => servingSet.has(d)).length}/${scoredAgainst.length} of the domains the old server served.`
          : "")
    );
    if (unservedDomains.length) {
      await report(
        97,
        "Finalising…",
        `NOT serving on the new server: ${unservedDomains.slice(0, 12).join(", ")}${unservedDomains.length > 12 ? ` and ${unservedDomains.length - 12} more` : ""} — do not move DNS for ${unservedDomains.length === 1 ? "this name" : "these names"} yet.`
      );
    }
    if (unitBlockers.length) {
      await report(
        97,
        "Finalising…",
        `Services that are not running: ${unitBlockers.slice(0, 12).map((b) => b.domain).join(", ")}${unitBlockers.length > 12 ? " …" : ""} — each is listed in the summary with its actual error.`
      );
    }
    if (tlsPending.length) {
      await report(97, "Finalising…", `HTTPS still to finish: ${tlsPending.slice(0, 4).map((p) => p.domain).join(", ")}${tlsPending.length > 4 ? " …" : ""}`);
    }
    if (needsAttention.length) {
      await report(98, "Finalising…", `Needs a manual step: ${needsAttention.slice(0, 8).join(" | ")}${needsAttention.length > 8 ? " …" : ""}`);
    }
    await report(
      98,
      "Finalising…",
      outcome === "COMPLETED"
        ? "Outcome: COMPLETED — every domain the old server served is serving here."
        : `Outcome: COMPLETED_WITH_ISSUES — ${outcomeReasons.join("; ")}.`
    );

    return {
      results,
      verifiedRunning,
      needsAttention,
      tlsSecured,
      tlsPending,
      siteProbes,
      sourceDomains: scoredAgainst,
      unservedDomains,
      blockers: [...blockers, ...unitBlockers],
      outcome,
      outcomeReasons,
    };
  } finally {
    // Scrub every secret-bearing artefact from the target, always:
    //   - the source SSH password file,
    //   - the per-container env files (application secrets),
    //   - the MySQL account SQL (password hashes),
    //   - any Cloudflare DNS-01 credentials file.
    // DB dumps under ${work}/dumps are intentionally kept so a failed import can
    // be retried by hand; they hold data, not credentials.
    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
    await execRemote(
      conn,
      `find ${work}/env -type f -exec shred -u {} \\; 2>/dev/null; rm -rf ${work}/env; ` +
        `shred -u ${work}/dumps/mysql-users.sql ${work}/dumps/mysql-users.err ${work}/cf-dns.ini 2>/dev/null; ` +
        `rm -f ${work}/dumps/mysql-users.sql ${work}/dumps/mysql-users.err ${work}/cf-dns.ini; true`,
      SETUP_TIMEOUT_MS
    ).catch(() => {});
    try {
      conn.end();
    } catch {
      /* best-effort */
    }
  }
}

/** Where transient migration state (dumps) lands on the target, for the notice. */
export function migrationWorkDir(migrationId: string): string {
  return `/root/nxeon-migrations/${migration_id_safe(migrationId)}`;
}

function migration_id_safe(id: string): string {
  return /^[A-Za-z0-9_-]{1,64}$/.test(id) ? id : "invalid";
}

