361	
362	  const hasSelection = selectedPaths.length > 0 || detectedEngines.length > 0;
363	
364	  // ---- Storage guardrail — total to migrate vs. target free space ----------
365	  // Recomputes live as the customer checks/unchecks. Unknown-size items (custom
366	  // folders, Docker mounts) contribute 0; the DB estimate is added whenever an
367	  // engine is detected (databases are auto-included).
368	  /**
369	   * The move splits across two destinations, so we size them separately:
370	   *  - `fileBytes`   → the selected folders + databases, restored to their original
371	   *                    paths, i.e. onto the ROOT filesystem.
372	   *  - `dockerBytes` → Docker images (they unpack to roughly 2x while loading) plus
373	   *                    working headroom, which live under /var/lib/{docker,containerd}
374	   *                    — the engine relocates those onto an unused volume, but
375	   *                    ONLY if the customer opts in to using it.
376	   * Nothing ever needs `fileBytes + dockerBytes` contiguously, so testing the
377	   * combined total against a single disk understates what actually fits.
378	   */
379	  const { fileBytes, dockerBytes, totalBytes } = useMemo(() => {
380	    if (!scan) return { fileBytes: 0, dockerBytes: 0, totalBytes: 0 };
381	    const byPath = new Map<string, number>();
382	    scan.webRoots.forEach((w) => byPath.set(w.path, parseSize(w.sizeLabel)));
383	    scan.homes.forEach((h) => byPath.set(h.path, parseSize(h.sizeLabel)));
384	    scan.appDirs.forEach((a) => byPath.set(a.path, parseSize(a.sizeLabel)));
385	    let f = 0;
386	    for (const p of selectedPaths) f += byPath.get(p) ?? 0;
387	    if (detectedEngines.length > 0) f += Math.max(0, scan.dbSizeBytes ?? 0);
388	    const imageBytes = Math.max(0, scan.dockerImageBytes ?? 0);
389	    const d = imageBytes > 0 ? imageBytes * 2 + 2 * GiB : 0;
390	    return { fileBytes: f, dockerBytes: d, totalBytes: f + d };
391	  }, [scan, selectedPaths, detectedEngines]);
392	
393	  const storage = useMemo(() => {
394	    const disk = targetInfo?.disk ?? null;
395	    // Capacity sitting in an unused volume — OFFERED, not counted. It is the
396	    // largest single volume (the engine uses exactly one and never combines
397	    // them), and it only becomes usable space once the customer opts in.
398	    const spareOffered = Math.max(0, targetInfo?.spareDiskBytes ?? 0);
399	    const spareCount = Math.max(0, targetInfo?.spareDiskCount ?? 0);
400	    if (!disk) {
401	      return {
402	        state: "unknown" as StorageState,
403	        avail: 0, rootAvail: 0, spare: 0, spareOffered, spareCount,
404	        total: 0, diskTotal: 0, used: 0, margin: 0, deficitGB: 0,
405	      };
406	    }
407	    // The volume counts as capacity ONLY with explicit consent. Without it the
408	    // fit test is root-only: taking a portable volume to make a migration fit is
409	    // the customer's decision, so the verdict must reflect what they actually
410	    // chose rather than what we could do if we helped ourselves to their disk.
411	    const spare = useVolumeForDocker ? spareOffered : 0;
412	    const rootAvail = disk.availBytes;
413	    // Where each portion actually lands: files always on root; Docker's stores on
414	    // the volume when the customer opted in, otherwise also on root. Sizing the
415	    // two destinations separately is why opting in genuinely adds capacity even
416	    // though the root disk and the volume are separate filesystems.
417	    const dockerTarget = spare > 0 ? spare : rootAvail;
418	    const rootNeed = spare > 0 ? fileBytes : fileBytes + dockerBytes;
419	    const avail = spare > 0 ? rootAvail + spare : rootAvail;
420	    // Leave headroom for the OS/overhead: the larger of 2 GB or 10% of free space.
421	    const margin = Math.max(2 * GiB, rootAvail * 0.1);
422	    // The tighter of the two destinations decides the verdict.
423	    const rootSlack = rootAvail - rootNeed;
424	    const dockerSlack = dockerTarget - dockerBytes;
425	    const worstSlack = Math.min(rootSlack, dockerBytes > 0 ? dockerSlack : Infinity);
426	    let state: StorageState;
427	    if (worstSlack < 0) state = "wontfit";
428	    else if (worstSlack < margin) state = "tight";
429	    else state = "comfortable";
430	    // Extra space needed on whichever destination is short (data + margin).
431	    const deficitGB = Math.max(1, Math.ceil((margin - worstSlack) / GiB));
432	    return {
433	      state, avail, rootAvail, spare, spareOffered, spareCount,
434	      total: totalBytes, diskTotal: disk.totalBytes, used: disk.usedBytes, margin, deficitGB,
435	    };
436	  }, [targetInfo, totalBytes, useVolumeForDocker]);
437	
438	  // Hard block only when the data physically won't fit on the destination.
439	  const storageBlocks = storage.state === "wontfit";
440	
441	  // ---- OS / architecture compatibility (static — based on the scan) --------
442	  const compat = useMemo(() => {
443	    const items: CompatItem[] = [];
444	    const srcOs = scan?.sourceOs ?? null;
445	    const srcArch = scan?.sourceArch ?? null;
446	    const tgtArch = targetInfo?.arch ?? null;
447	    const tgtOs = targetInfo?.os ?? null;
448	
449	    const sa = normArch(srcArch);
450	    const ta = normArch(tgtArch);
451	    const archMismatch = !!sa && !!ta && sa !== ta;
452	
453	    const sFam = familyOf(srcOs?.id);
454	    const tFam = familyOf(tgtOs?.id);
455	    const familyMismatch = !!sFam && !!tFam && sFam !== tFam;
456	    const sameFamilyDiffMajor =
457	      !!sFam && sFam === tFam && !!srcOs?.versionId && !!tgtOs?.versionId &&
458	      srcOs.versionId.split(".")[0] !== tgtOs.versionId.split(".")[0];
459	
460	    if (archMismatch) {
461	      items.push({
462	        level: "critical",
463	        title: `Different CPU architecture (${sa} → ${ta})`,
464	        body: (
465	          <>
466	            Your old server is <span className="font-mono">{sa}</span> but your Nxeon server is{" "}
467	            <span className="font-mono">{ta}</span>. Your files and database dumps still migrate fine, but{" "}
468	            <strong>compiled programs and Docker images built for {sa} will not run</strong> on {ta}. Check anything
469	            custom-compiled or containerised before relying on it.
470	          </>
471	        ),
472	      });
473	    }
474	
475	    if (familyMismatch) {
476	      const suggestion = srcOs ? closestOsTemplate(srcOs.id, srcOs.versionId, osTemplates) : null;
477	      items.push({
478	        level: "warn",
479	        title: `Different OS family (${FAMILY_LABEL[sFam] ?? sFam} → ${FAMILY_LABEL[tFam] ?? tFam})`,
480	        body: (
481	          <>
482	            OS-level packages, service unit paths and config locations differ between these families. We install
483	            equivalents from our catalog where we can, but system services and custom-compiled apps may need manual
484	            setup afterwards. <strong>Docker containers, database dumps and plain files port across distros fine.</strong>
485	            {suggestion && (
486	              <>
487	                {" "}
488	                For the smoothest migration, consider reinstalling this Nxeon server with{" "}
489	                <a className="font-medium text-brand-300 underline hover:text-brand-200" href={`/dashboard/servers/${serverId}?tab=resize`}>
490	                  {suggestion.name}
491	                  {suggestion.version ? ` ${suggestion.version}` : ""}
492	                </a>{" "}
493	                so it matches your old server (this erases the new server — do it before you migrate).
494	              </>
495	            )}
496	          </>
497	        ),
498	      });
499	    } else if (sameFamilyDiffMajor) {
500	      items.push({
501	        level: "note",
502	        title: `Same OS family, different version (${srcOs!.pretty || srcOs!.versionId} → ${tgtOs!.pretty || tgtOs!.versionId})`,
503	        body: <>Same distro family, different major version — usually fine. Occasionally a package needs a newer/older build.</>,
504	      });
505	    }
506	
507	    // Database engine: we install the SAME engine variant the source uses, so the
508	    // restore is a clean same-engine import. Green note on the clean path; the honest
509	    // amber caveat only when we can't determine the variant (the genuine fallback risk).
510	    if (detectedEngines.includes("mysql")) {
511	      const detail = (scan?.dbEngines ?? []).find((d) => d.engine === "mysql");
512	      const variant = detail?.variant ?? null;
513	      const version = detail?.version ?? null;
514	      if (variant === "mysql") {
515	        const major = version ? version.split(".")[0] : "8";
516	        items.push({
517	          level: "good",
518	          title: `We'll install MySQL ${major} on your new server to match your old one`,
519	          body: <>Your old server runs Oracle MySQL{version ? ` ${version}` : ""}, so we set up the same MySQL {major} on your new server — a clean same-engine import, no changes needed.</>,
520	        });
521	      } else if (variant === "mariadb") {
522	        items.push({
523	          level: "good",
524	          title: `We'll install MariaDB${version ? ` ${version}` : ""} on your new server to match your old one`,
525	          body: <>Your old server runs MariaDB{version ? ` ${version}` : ""}, so we set up the same MariaDB on your new server — a clean same-engine import, no changes needed.</>,
526	        });
527	      } else {
528	        // Variant undeterminable → default to MariaDB and be honest about the tweaks.
529	        items.push({
530	          level: "warn",
531	          title: "MySQL → MariaDB",
532	          body: <>We couldn&apos;t confirm your exact MySQL variant, so we set up MariaDB on the new server. Your dump imports in almost all cases; a few edge cases (auth plugins, uncommon storage engines) may need a small tweak.</>,
533	        });
534	      }
535	    }
536	
537	    // PostgreSQL: same major-family engine on the target; pg_dumpall restores import
538	    // cleanly. (A wildly older target major taking a newer dump is the only caveat.)
539	    if (detectedEngines.includes("postgres")) {
540	      const detail = (scan?.dbEngines ?? []).find((d) => d.engine === "postgres");
541	      const version = detail?.version ?? null;
542	      items.push({
543	        level: "good",
544	        title: "We'll install PostgreSQL on your new server to match your old one",
545	        body: <>We set up PostgreSQL on your new server{version ? ` to match your source (PostgreSQL ${version})` : ""} and restore it with pg_dumpall — a clean same-engine import, no changes needed.</>,
546	      });
547	    }
548	
549	    const allMatch =
550	      items.length === 0 && !!sa && !!ta && sa === ta && !!sFam && !!tFam && sFam === tFam;
551	
552	    return { items, allMatch, haveTargetInfo: !!tgtOs || !!tgtArch };
553	  }, [scan, targetInfo, osTemplates, serverId, detectedEngines]);
554	
555	  async function launch() {
556	    setSubmitting(true);
557	    setError(null);
558	    try {
559	      const res = await createMigration({
560	        serverId,
561	        sourceHost: host.trim(),
562	        sourcePort: portNum,
563	        sourceUser: user.trim(),
564	        sourcePassword: password,
565	        paths: selectedPaths,
566	        // Explicit, opt-in only. False means the engine leaves every attached
567	        // volume completely alone and fails the pre-flight if root is too small,
568	        // rather than quietly making a portable volume undetachable.
569	        useVolumeForDocker,
570	        // No DB credentials collected — databases are dumped passwordlessly via
571	        // root's local auth on the source and derived server-side from the scan.
572	        scan: scan ?? undefined,
573	      });
574	      if (res.error) {
575	        setError(res.error);
576	      } else if (res.id) {
577	        // Drop the plaintext SSH password from client memory once it's stored.
578	        setPassword("");
579	        setActiveId(res.id);
580	      }
581	    } catch {
582	      setError("Something went wrong starting the migration. Please try again.");
583	    } finally {
584	      setSubmitting(false);
585	    }
586	  }
587	
588	  if (activeId) {
589	    return <MigrationProgress id={activeId} onDone={() => setActiveId(null)} />;
590	  }
591	
592	  const serverName = servers.find((s) => s.id === serverId)?.name ?? "—";
593	
594	  // Dedicated scanning view.
595	  if (scanning) {
596	    return (
597	      <div className="card">
598	        <Stepper step={1} />
599	        <div className="flex flex-col items-center justify-center py-14 text-center">
600	          <div className="mb-5 h-10 w-10 animate-spin rounded-full border-2 border-white/15 border-t-brand-400" />
601	          <h2 className="mb-1 font-semibold">Scanning your server…</h2>
602	          <p className="max-w-md text-sm text-slate-400">
603	            We&apos;re connecting to <span className="font-mono text-slate-300">{host.trim()}</span> read-only to find
604	            your websites, files and databases. Nothing on your old server is changed. This usually takes under a minute.
605	          </p>
606	        </div>
607	      </div>
608	    );
609	  }

1076	/** Storage headroom panel: total to migrate vs. free space on the destination. */
1077	function StoragePanel({
1078	  storage,
1079	  serverId,
1080	  useVolume,
1081	  onUseVolumeChange,
1082	}: {
1083	  storage: {
1084	    state: StorageState;
1085	    /** Effective usable space: root free space, plus the volume IF opted in. */
1086	    avail: number;
1087	    /** Free space on the main (root) filesystem. */
1088	    rootAvail: number;
1089	    /** Volume capacity actually being counted — 0 unless the customer opted in. */
1090	    spare: number;
1091	    /** Capacity of the largest unused volume, whether or not it is being used. */
1092	    spareOffered: number;
1093	    /** How many unused volumes are attached (only the largest can be used). */
1094	    spareCount: number;
1095	    total: number;
1096	    diskTotal: number;
1097	    used: number;
1098	    deficitGB: number;
1099	  };
1100	  serverId: string;
1101	  /** Explicit opt-in to use the volume for Docker storage. Default OFF. */
1102	  useVolume: boolean;
1103	  onUseVolumeChange: (next: boolean) => void;
1104	}) {
