    let covered = false;
    for (const n of site.names) {
      if (await certExists(conn, n)) {
        secured.push(...site.names);
        await say(`  ${n}: HTTPS already covered by the certificate migrated from the old server.`);
        covered = true;
        break;
      }
    }
    if (covered) continue;

    // 3. Wildcard via DNS-01 — the ONLY way to get `*.domain`.
    const bases = wildcardBasesFor(site);
    if (bases.length && cloudflareToken) {
      let anyOk = false;
      for (const base of bases) {
        // DNS-01 waits 45s for propagation before it even asks the CA, so it is
        // always a multi-minute step — it narrates itself.
        const r = await withHeartbeat(`issuing the wildcard certificate for *.${base} (waiting for DNS to propagate)`, say, () =>
          issueDns01(conn, sftp, work, cloudflareToken, base, [`*.${base}`, base], email)
