            domain: `*.${base}`,
            why: `the wildcard certificate could not be issued (${r.err || "unknown error"})`,
            fix: `certbot certonly --dns-cloudflare --dns-cloudflare-credentials <cloudflare.ini> -d '*.${base}' -d ${base}`,
          });
        }
      }
      if (anyOk) continue;
