      pending.push({
        domain: `*.${bases[0]}`,
        why:
          "this app gives each tenant its own subdomain, which needs a wildcard certificate — and a wildcard can only be issued with a DNS-01 challenge. Connect Cloudflare in Settings and we can issue it for you automatically",
        fix: `certbot certonly --manual --preferred-challenges dns -d '*.${bases[0]}' -d ${bases[0]}`,
      });
    }

