    if (webOwnedByContainer) {
      pending.push({
        domain: site.names[0],
        why: "port 80 is served by one of your containers, so the certificate check cannot run on the host",
        fix: `issue TLS inside your proxy container (Traefik and Caddy do this automatically once ${site.names[0]} resolves here)`,
      });
      continue;
    }
    const resolving: string[] = [];
    for (const n of site.names) if (await resolvesHere(conn, n, targetIp)) resolving.push(n);
    if (!resolving.length) {
      pending.push({
        domain: site.names[0],
        why: `${site.names.length > 1 ? "none of these names point" : "this name does not point"} at the new server yet${targetIp ? ` (${targetIp})` : ""}, and a certificate cannot be issued until DNS moves`,
        fix: `point the DNS, then run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${site.names[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
      });
      continue;
    }
    const r = await withHeartbeat(`requesting the certificate for ${resolving.slice(0, 3).join(", ")}`, say, () =>
      issueHttp01(conn, resolving[0], resolving, email)
    );
    if (r.ok) {
      secured.push(...resolving);
      await say(`  Issued a certificate for ${resolving.join(", ")}.`);
      const notYet = site.names.filter((n) => !resolving.includes(n));
      if (notYet.length) {
        pending.push({
          domain: notYet[0],
          why: `${notYet.join(", ")} ${notYet.length > 1 ? "do" : "does"} not point at the new server yet, so ${notYet.length > 1 ? "they were" : "it was"} left out of the certificate`,
          fix: `point the DNS, then run: certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${site.names.map((d) => `-d ${d}`).join(" ")}`,
        });
      }
    } else {
      pending.push({
        domain: resolving[0],
        why: `the certificate request failed (${r.err || "unknown error"})`,
        fix: `certbot certonly --webroot -w ${ACME_WEBROOT} --cert-name ${resolving[0]} ${resolving.map((d) => `-d ${d}`).join(" ")}`,
      });
    }
  }

  if (secured.length) {
    const applied = await applyCertsAndReload(conn, sftp, work, spec);
    if (!applied.ok) {
      pending.push({
        domain: spec.sites[0]?.names[0] ?? "",
        why: `certificates were issued but the web server would not take the updated config (${applied.detail})`,
        fix: "check `nginx -t` / `apachectl configtest` on the server",
      });
    }
  }
  return { secured: [...new Set(secured)], pending };
}

