async function relocateDockerStores(
  conn: Client,
  say: (line: string) => Promise<void>
): Promise<{ moved: string[]; failed: string[] }> {
  const moved: string[] = [];
  const failed: string[] = [];
  await sh(conn, `systemctl stop docker.socket docker containerd 2>/dev/null; true`, SETUP_TIMEOUT_MS);

  for (const store of DOCKER_STORES) {
    const leaf = store.slice(store.lastIndexOf("/") + 1);
    const dest = `${EXTRA_DISK_MOUNT}/${leaf}`;
    // Already relocated (a re-run, or the previous attempt got this far)?
    const already = await sh(conn, `findmnt -n -o SOURCE --target ${store} 2>/dev/null`);
    if (clean(already.stdout, 255).startsWith(EXTRA_DISK_MOUNT)) {
      moved.push(`${store} (already on ${EXTRA_DISK_MOUNT})`);
      continue;
    }
    await sh(conn, `mkdir -p ${dest} ${store}`);
    const cp = await sh(conn, `rsync -a --numeric-ids ${store}/ ${dest}/ 2>&1`, TRANSFER_TIMEOUT_MS);
    if (cp.code !== 0) {
      failed.push(`${store}: copy failed (${tailOf(cp)})`);
      continue;
    }
    await sh(
      conn,
      `grep -q " ${store} none bind" /etc/fstab || printf '%s %s none bind,nofail 0 0\\n' '${dest}' '${store}' >> /etc/fstab`
    );
    // Empty the original only AFTER the copy succeeded, and keep it aside until
    // the bind mount is confirmed.
    await sh(conn, `rm -rf ${store}.premigrate && mv ${store} ${store}.premigrate && mkdir -p ${store}`, SETUP_TIMEOUT_MS);
    const mnt = await sh(conn, `mount --bind ${dest} ${store} 2>&1`, SETUP_TIMEOUT_MS);
    const live = await shOk(conn, `mountpoint -q ${store}`);
    if (!live) {
      // Roll back cleanly — better a full root disk than a broken Docker.
      await sh(conn, `rmdir ${store} 2>/dev/null; mv ${store}.premigrate ${store} 2>/dev/null; true`);
      await sh(conn, `sed -i '\\| ${store} none bind|d' /etc/fstab 2>/dev/null; true`);
      failed.push(`${store}: bind mount failed (${tailOf(mnt)}) — left in place`);
      continue;
    }
    await sh(conn, `rm -rf ${store}.premigrate 2>/dev/null; true`, SETUP_TIMEOUT_MS);
    moved.push(store);
  }

  await sh(conn, `systemctl enable --now containerd 2>/dev/null; systemctl enable --now docker 2>/dev/null; true`, INSTALL_TIMEOUT_MS);
  const df = await sh(conn, `df -h ${DOCKER_STORES.join(" ")} 2>/dev/null | tail -n +2`);
  const dfTail = clean(df.stdout, 400).split("\n").map((l) => l.trim()).filter(Boolean).join(" | ");
  if (dfTail) await say(`  Docker storage now: ${dfTail}`);
  return { moved, failed };
}

/**
 * Reclaim build/ingest space. `docker builder prune -af` reclaimed 7.1 GB in the
 * field immediately after two image builds, which is the difference between a
 * working bring-up and ENOSPC. Dangling images go too. Deliberately NOT
 * `image prune -a` / `container prune` — those would delete images we have just
 * transferred but not yet started.
 */
async function pruneDocker(conn: Client): Promise<number> {
  const before = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
  await sh(conn, `docker builder prune -af >/dev/null 2>&1; docker image prune -f >/dev/null 2>&1; true`, INSTALL_TIMEOUT_MS);
  const after = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
  return Math.max(0, after - before);
}

