  conn: Client,
  ref: string,
  local: boolean,
  onSource: (cmd: string) => string,
  priv: string,
  say: (line: string) => Promise<void>
): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };

  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
    return { status: "present", detail: "already on the new server" };
  }

async function ensureImage(
  conn: Client,
  ref: string,
  local: boolean,
  onSource: (cmd: string) => string,
  priv: string,
  say: (line: string) => Promise<void>
): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };

  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
    return { status: "present", detail: "already on the new server" };
  }

  if (!local) {
    // A multi-gigabyte pull is one of the three steps that can sit silent for
    // minutes, so it narrates itself (see withHeartbeat).
    const pull = await withHeartbeat(`downloading the container image ${ref}`, say, () =>
      sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS)
    );
    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
      return { status: "pulled", detail: "pulled from its registry" };
    }
    const why = tailOf(pull, 1, 120);
    await say(`  ${ref}: pull failed (${why || "unavailable"}) — transferring it from the old server instead.`);
  }

  // `docker save | gzip -1` on the source → `gunzip | docker load` on the target,
  // through the SSH channel we already hold. gzip -1 because these links are
  // usually faster than the CPU and the layers are mostly already compressed.
  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
  const r = await withHeartbeat(`transferring the container image ${ref} from the old server`, say, () =>
    sh(conn, stream, IMAGE_TIMEOUT_MS)
  );
  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
    return { status: "loaded", detail: "transferred from the old server (docker save/load)" };
  }
  const why = tailOf(r, 2, 180);
  return {
    status: "failed",
    detail: isEnospc(why)
      ? "ran out of disk while loading the image"
      : `could not pull or transfer the image${why ? `: ${why}` : ""}`,
  };
}

