function mysqlGrantsScript(priv: string, accounts: { user: string; host: string }[]): string {
  const specs = accounts.map((a) => `${a.user}:${a.host}`).join(" ");
  return [
    "export LC_ALL=C",
    'PRIV="' + priv + '"',
    "printf -- '-- application accounts migrated by Nxeon\\n'",
    "for spec in " + specs + "; do",
    "  u=${spec%%:*}",
    "  h=${spec#*:}",
    '  $PRIV mysql -N -B -e "SHOW CREATE USER \'$u\'@\'$h\'" 2>/dev/null | sed -e \'s/^CREATE USER /CREATE USER IF NOT EXISTS /\' -e \'s/$/;/\'',
    '  $PRIV mysql -N -B -e "SHOW GRANTS FOR \'$u\'@\'$h\'" 2>/dev/null | sed -e \'s/$/;/\'',
    "done",
    "",
  ].join("\n");
}

