      say: (l) => report(90, "Re-enabling services…", l),
    });
    for (const fix of pf.repairs) push({ step: `Repair ${svc} before starting it`, status: "running", detail: fix });
    if (!pf.ok) {
      // Do NOT enable a unit we already know cannot exec: enabling it just
      // starts a crash-loop that survives every reboot.
      unitBlockers.push(...pf.blockers);
      for (const b of pf.blockers) {
        push({ step: `Service ${svc} was NOT started`, status: "failed", detail: `${b.why}. To finish: ${b.fix}` });
      }
      await report(90, "Re-enabling services…", `  ${svc}: not started — ${pf.blockers[0].why}.`);
      continue;
    }

    await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
    const en = await execRemote(conn, `systemctl enable --now ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    const active = await execRemote(conn, `systemctl is-active ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
    enabledUnits.push(svc);
    // HELD, not pushed: `is-active` read one instant after `enable --now` is
    // not evidence, and recording "running" now would put a crash-looping
    // unit into the verified-running count. The gate below decides.
    heldUnitResults.set(
      svc,
      en.code === 0 && active
        ? { step: `Service ${svc}`, status: "running", detail: "unit copied, enabled and active" }
        : { step: `Service ${svc}`, status: "copied", detail: "unit copied but not confirmed active — check `systemctl status`" }
    );
