#!/bin/bash
# Create a complete, restorable migration bundle on the CURRENT (old) server.
# Read-only w.r.t. running services — safe to run anytime. Output goes to
# /tank/backup/migration/<timestamp>/. Copy that directory to the new box.
set -euo pipefail

TS=$(date +%Y%m%d-%H%M%S)
OUT="/tank/backup/migration/${TS}"
mkdir -p "$OUT/vms"
echo "==> Migration bundle: $OUT"

echo "==> 1/5 Dumping databases"
for DB in nxeon nxeon_staging; do
  sudo -u postgres pg_dump --no-owner --no-privileges "$DB" | gzip > "$OUT/${DB}.sql.gz"
  echo "    $DB -> ${DB}.sql.gz ($(du -h "$OUT/${DB}.sql.gz" | cut -f1))"
done

echo "==> 2/5 Backing up VMs + templates (vzdump)"
# Customer VMs (>=100, <9000) + templates (9000-9999)
VMIDS=$(qm list | awk 'NR>1 && $1>=100 {print $1}')
for VMID in $VMIDS; do
  echo "    vzdump $VMID ..."
  vzdump "$VMID" --dumpdir "$OUT/vms" --mode snapshot --compress zstd >/dev/null 2>&1 \
    && echo "      ok" || echo "      WARN: vzdump $VMID failed (VM may be locked) — retry manually"
done

echo "==> 3/5 Copying secrets + config"
mkdir -p "$OUT/config"
cp -a /opt/nxeon/.env "$OUT/config/nxeon.env" 2>/dev/null || true
cp -a /opt/nxeon-staging/.env "$OUT/config/nxeon-staging.env" 2>/dev/null || true
cp -a /etc/nxeon "$OUT/config/etc-nxeon" 2>/dev/null || true
cp -a /etc/systemd/system/nxeon-*.service /etc/systemd/system/nxeon-*.timer "$OUT/config/" 2>/dev/null || true
cp -a /etc/nginx/sites-available/nxeon /etc/nginx/sites-available/nxeon-staging "$OUT/config/" 2>/dev/null || true
chmod -R 600 "$OUT/config"

echo "==> 4/5 Recording repo commit + manifest"
GITSHA=$(git -C /opt/nxeon rev-parse HEAD 2>/dev/null || echo unknown)
OLD_IP=$(grep -oP 'PUBLIC_IP=\K.*' /opt/nxeon/.env 2>/dev/null || echo unknown)
{
  echo "Nxeon migration bundle"
  echo "created: $TS"
  echo "old_public_ip: $OLD_IP"
  echo "git_commit: $GITSHA  (github.com/santino1233/nxeon)"
  echo "databases: nxeon.sql.gz nxeon_staging.sql.gz"
  echo "vms:"; ls -1 "$OUT/vms" | sed 's/^/  /'
  echo "config: $(ls "$OUT/config" | tr '\n' ' ')"
  echo ""
  echo "RESTORE: see /opt/nxeon/docs/MIGRATION.md (Strategy B)."
} > "$OUT/MANIFEST.txt"

echo "==> 5/5 Done"
echo "Bundle size: $(du -sh "$OUT" | cut -f1)"
echo "Copy to new box, e.g.:  rsync -avP $OUT/ root@NEW_IP:/tank/backup/migration/${TS}/"
echo "Then follow docs/MIGRATION.md."
cat "$OUT/MANIFEST.txt"
