// ---- Timeouts -------------------------------------------------------------

function acmeAccountArgs(email: string): string {
  return email && EMAIL_RE.test(email) ? `-m ${email} --no-eff-email` : "--register-unsafely-without-email";
}

/** HTTP-01 via webroot. `certName` fixes the /etc/letsencrypt/live/<name> directory. */
async function issueHttp01(conn: Client, certName: string, domains: string[], email: string): Promise<{ ok: boolean; err: string }> {
  const ds = [...new Set(domains.filter((d) => DOMAIN_RE.test(d)))].slice(0, 20);
  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
  const cmd =
    `certbot certonly --webroot -w ${ACME_WEBROOT} -n --agree-tos ${acmeAccountArgs(email)} ` +
    `--keep-until-expiring --cert-name ${certName} ${ds.map((d) => `-d ${d}`).join(" ")} 2>&1`;
  const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
  if (await certExists(conn, certName)) return { ok: true, err: "" };
  return { ok: false, err: tailOf(r, 2, 220) };
}

/**
 * DNS-01 via the customer's connected Cloudflare account — the only way to get a
 * wildcard. The token never appears in argv: it is written to a 0600 credentials
 * file over SFTP and shredded immediately afterwards, success or failure.
 */
async function issueDns01(
  conn: Client,
  sftp: SFTPWrapper,
  work: string,
  token: string,
  certName: string,
  domains: string[],
  email: string
): Promise<{ ok: boolean; err: string }> {
  if (!token || token.length > 512 || /[\r\n]/.test(token)) return { ok: false, err: "unusable Cloudflare token" };
  const ds = [...new Set(domains)].filter((d) => DOMAIN_RE.test(d.replace(/^\*\./, ""))).slice(0, 20);
  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
  const ini = `${work}/cf-dns.ini`;
  try {
    await sftpWrite(sftp, ini, `dns_cloudflare_api_token = ${token}\n`);
    await sh(conn, `chmod 600 ${ini}`);
    const cmd =
      `certbot certonly --dns-cloudflare --dns-cloudflare-credentials ${ini} --dns-cloudflare-propagation-seconds 45 ` +
      `-n --agree-tos ${acmeAccountArgs(email)} --keep-until-expiring --cert-name ${certName} ` +
      `${ds.map((d) => `-d '${d}'`).join(" ")} 2>&1`;
    const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
    if (await certExists(conn, certName)) return { ok: true, err: "" };
    return { ok: false, err: tailOf(r, 2, 220) };
  } finally {
    await sh(conn, `shred -u ${ini} 2>/dev/null || rm -f ${ini}`).catch(() => {});
  }
}

/**
 * A wildcard covers exactly ONE label, so a multi-tenant app that also has a
 * staging tier (`hq.stg.example.com`) needs `*.stg.example.com` as well as
 * `*.example.com`. Return every base that needs its own wildcard.
 */
function wildcardBasesFor(site: TargetSite): string[] {
  const bases = new Set<string>();
  if (site.wildcard) bases.add(site.wildcard);
  for (const n of site.names) {
    const parts = n.split(".");
    if (parts.length < 3) continue;
    const parent = parts.slice(1).join(".");
    if (site.wildcard && parent !== site.wildcard && parent.endsWith(`.${site.wildcard}`)) bases.add(parent);
  }
